package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.item.context.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.*;import net.minecraft.network.chat.Component;import java.util.*;
public final class AdcItem extends BlockItem{
 public AdcItem(Block b,Properties p){super(b,p);}public static BlockPos anchor(BlockPos p,Direction face){return p.relative(face.getOpposite(),3);}
 @Override public InteractionResult useOn(UseOnContext c){if(c.getPlayer()!=null&&c.getPlayer().isShiftKeyDown()){var n=DefenseItem.data(c.getItemInHand());n.putInt("DefenseRotation",(n.getInt("DefenseRotation")+1)&3);DefenseItem.data(c.getItemInHand(),n);return InteractionResult.SUCCESS;}return super.useOn(c);}
 @Override public BlockPlaceContext updatePlacementContext(BlockPlaceContext c){if(c.getClickedFace()!=Direction.UP)return null;var at=anchor(c.getClickedPos(),DefenseItem.face(c.getPlayer(),c.getItemInHand()));return new BlockPlaceContext(c.getLevel(),c.getPlayer(),c.getHand(),c.getItemInHand(),new BlockHitResult(Vec3.atCenterOf(at),Direction.UP,at,false));}
 public static String check(Level l,BlockPos root,Direction f,net.minecraft.world.entity.player.Player p,ItemStack s){for(var c:AdcGeometry.MODEL.cells){var at=AdcGeometry.MODEL.cell(root,f,c);if(at.getY()<l.getMinBuildHeight()||at.getY()>=l.getMaxBuildHeight())return "HEIGHT";if(!l.hasChunkAt(at))return "UNLOADED";if(!l.getWorldBorder().isWithinBounds(at)||p!=null&&(!l.mayInteract(p,at)||!p.mayUseItemAt(at,Direction.UP,s)))return "DENIED";if(!l.getBlockState(at).isAir())return "BLOCKED";}for(var c:AdcGeometry.MODEL.support){var at=AdcGeometry.MODEL.cell(root,f,c).below();if(!l.getBlockState(at).isFaceSturdy(l,at,Direction.UP))return "FOUNDATION";}var bounds=AdcGeometry.transform(AdcGeometry.world(root,f),AdcGeometry.MODEL.bounds);if(!l.getEntities((net.minecraft.world.entity.Entity)null,bounds,e->!e.isSpectator()&&!(e instanceof net.minecraft.world.entity.item.ItemEntity)&&!(e instanceof net.minecraft.world.entity.ExperienceOrb)).isEmpty())return "OCCUPIED";return "";}
 @Override protected boolean canPlace(BlockPlaceContext c,BlockState s){var why=check(c.getLevel(),c.getClickedPos(),s.getValue(AdcBlock.FACING),c.getPlayer(),c.getItemInHand());if(!why.isEmpty()&&c.getPlayer()!=null)c.getPlayer().displayClientMessage(Component.translatable("defense.status."+why),true);return why.isEmpty()&&super.canPlace(c,s);}
 @Override protected boolean placeBlock(BlockPlaceContext c,BlockState s){var done=new ArrayList<BlockPos>();AdcBlock.MUTATING.set(true);try{for(int i=0;i<AdcGeometry.MODEL.cells.length;i++){var at=AdcGeometry.MODEL.cell(c.getClickedPos(),s.getValue(AdcBlock.FACING),AdcGeometry.MODEL.cells[i]);if(!c.getLevel().setBlock(at,s.setValue(AdcBlock.PART,i),3)){for(var p:done)c.getLevel().removeBlock(p,false);return false;}done.add(at);}return true;}finally{AdcBlock.MUTATING.set(false);}}
 @Override public void appendHoverText(ItemStack s,Level l,List<Component>text,TooltipFlag f){text.add(Component.translatable("adc01.description"));text.add(Component.translatable("defense.placement"));}
 @Override public void initializeClient(java.util.function.Consumer<net.minecraftforge.client.extensions.common.IClientItemExtensions>c){c.accept(new net.minecraftforge.client.extensions.common.IClientItemExtensions(){@Override public net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer getCustomRenderer(){return AdcItemRenderer.instance();}});}
}
